import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int[] answer = new int[nums.length - k + 1];
        int write = 0;

        // 只存下标，并让对应值从队首到队尾递减，队首才始终是最大值。
        Deque<Integer> deque = new ArrayDeque<>();

        for (int right = 0; right < nums.length; right++) {
            // 队尾更小或相等的值被 nums[right] 盖住，之后不可能成为窗口最大值。
            while (!deque.isEmpty() && nums[deque.peekLast()] <= nums[right]) {
                deque.pollLast();
            }
            deque.offerLast(right);

            // 队首下标已经滑出左边界，不能再代表当前窗口。
            if (deque.peekFirst() <= right - k) {
                deque.pollFirst();
            }

            // 第一个完整窗口形成后，队首就是当前窗口最大值。
            if (right >= k - 1) {
                answer[write++] = nums[deque.peekFirst()];
            }
        }
        return answer;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int[] answer = new int[temperatures.length];

        // 只留还没遇到更高温度的下标，温度从栈底到栈顶单调不增。
        Deque<Integer> stack = new ArrayDeque<>();

        for (int day = 0; day < temperatures.length; day++) {
            while (!stack.isEmpty()
                    && temperatures[stack.peek()] < temperatures[day]) {
                int previousDay = stack.pop();
                answer[previousDay] = day - previousDay;
            }

            stack.push(day);
        }

        // 栈里剩下的下标右侧没有更高温度，答案保持 0。
        return answer;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int largestRectangleArea(int[] heights) {
        Deque<Integer> stack = new ArrayDeque<>();
        int best = 0;

        // 末尾补高度 0 的哨兵，结算所有正高度柱子；零高度无需贡献面积。
        for (int i = 0; i <= heights.length; i++) {
            int currentHeight = (i == heights.length) ? 0 : heights[i];

            // 更矮的柱子出现后，栈顶柱子向右不能再扩展。
            while (!stack.isEmpty() && heights[stack.peek()] > currentHeight) {
                int top = stack.pop();
                int leftLess = stack.isEmpty() ? -1 : stack.peek();
                int width = i - leftLess - 1;

                best = Math.max(best, heights[top] * width);
            }

            stack.push(i);
        }

        return best;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public boolean isValid(String s) {
        // 未闭合的左括号只能按逆序被右括号关掉，所以只压左括号。
        Deque<Character> stack = new ArrayDeque<>();

        for (char c : s.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
                continue;
            }

            // 没有可配对的左括号，或类型对不上，都不能闭合。
            if (stack.isEmpty()) return false;
            char left = stack.pop();

            if ((c == ')' && left != '(')
                    || (c == ']' && left != '[')
                    || (c == '}' && left != '{')) {
                return false;
            }
        }

        // 栈空才表示每个左括号都已被对应右括号关掉。
        return stack.isEmpty();
    }
}

import java.util.*;

class Solution {
    public boolean isValidWithPriority(String s) {
        Map<Character, Character> pair = Map.of(
                ')', '(',
                ']', '[',
                '}', '{');

        // 数字越大优先级越高，外层必须不低于内层。
        Map<Character, Integer> rank = Map.of(
                '(', 1,
                '[', 2,
                '{', 3);

        Deque<Character> stack = new ArrayDeque<>();

        for (char c : s.toCharArray()) {
            if (rank.containsKey(c)) {
                // 栈顶是外层；新的内层不能比外层等级更高。
                if (!stack.isEmpty() && rank.get(c) > rank.get(stack.peek())) {
                    return false;
                }
                stack.push(c);
            } else if (pair.containsKey(c)) {
                if (stack.isEmpty() || stack.pop() != pair.get(c)) {
                    return false;
                }
            } else {
                // 只接受这六种括号字符。
                return false;
            }
        }

        return stack.isEmpty();
    }
}

class Solution {
    public boolean checkValidString(String s) {
        int low = 0, high = 0; // 未匹配左括号的下界与上界
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                low++;
                high++;
            } else if (c == ')') {
                if (low > 0) {
                    low--;
                }
                high--;
            } else {
                if (low > 0) { // * 尽量当右括号压低下界
                    low--;
                }
                high++; // * 同时可以当左括号，抬高上界
            }
            if (high < 0) {
                return false; // 右括号已经不可能被配平
            }
        }
        return low == 0;
    }
}

class Solution {
    public int minAddToMakeValid(String s) {
        int balance = 0, ans = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                balance++;
            } else {
                if (balance > 0) {
                    balance--; // 用已有左括号配对
                } else {
                    ans++; // 这个右括号必须补一个左括号
                }
            }
        }
        return ans + balance; // 剩余左括号各补一个右括号
    }
}

import java.util.*;

class Solution {
    public String minRemoveToMakeValid(String s) {
        char[] arr = s.toCharArray();
        Deque<Integer> stack = new ArrayDeque<>(); // 未匹配左括号的下标
        boolean[] removed = new boolean[arr.length];
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == '(') {
                stack.push(i);
            } else if (arr[i] == ')') {
                if (stack.isEmpty()) {
                    removed[i] = true; // 没有左括号可配，删掉这个右括号
                } else {
                    stack.pop();
                }
            }
        }
        while (!stack.isEmpty()) {
            removed[stack.pop()] = true; // 剩余左括号同样删掉
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < arr.length; i++) {
            if (!removed[i]) {
                sb.append(arr[i]);
            }
        }
        return sb.toString();
    }
}

class Solution {
    public int minInsertions(String s) {
        int ans = 0, need = 0; // need：还缺的右括号个数
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if ((need & 1) == 1) {
                    ans++; // 奇数个缺口无法被新左括号接上，先补一个 )
                    need--;
                }
                need += 2;
            } else {
                need--;
                if (need == -1) {
                    ans++; // 多出一个 )，插入一个 (
                    need = 1;
                }
            }
        }
        return ans + need;
    }
}

class Solution {
    public int minSwaps(String s) {
        int balance = 0, minBalance = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') {
                balance++;
            } else {
                balance--;
                minBalance = Math.min(minBalance, balance); // 记录最深的 ] 过剩
            }
        }
        return (-minBalance + 1) / 2; // 一次交换消掉两个失衡
    }
}

import java.util.*;

class Solution {
    public int scoreOfParentheses(String s) {
        // 栈记外层分数，cur 记当前层
        Deque<Integer> stack = new ArrayDeque<>();
        int cur = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                // 进入更深层前先保存外层并清空当前层
                stack.push(cur);
                cur = 0;
            } else {
                // 空层记 1，否则记 2*cur，再加回外层
                cur = stack.pop() + Math.max(2 * cur, 1);
            }
        }
        return cur;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public String decodeString(String s) {
        // 进入 '[' 前，外层已经拼好的字符串要先存起来。
        Deque<StringBuilder> stringStack = new ArrayDeque<>();
        // 每个 '[' 对应它前面刚读完的重复次数。
        Deque<Integer> countStack = new ArrayDeque<>();

        StringBuilder current = new StringBuilder();
        int number = 0;

        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                // 次数可能不止一位，例如 12[a]。
                number = number * 10 + (c - '0');
            } else if (c == '[') {
                countStack.push(number);
                stringStack.push(current);

                // 新的一层从空片段重新开始收集。
                number = 0;
                current = new StringBuilder();
            } else if (c == ']') {
                int repeat = countStack.pop();
                StringBuilder parent = stringStack.pop();

                // 当前层重复 repeat 次后接回外层。
                for (int i = 0; i < repeat; i++) {
                    parent.append(current);
                }
                current = parent;
            } else {
                current.append(c);
            }
        }

        return current.toString();
    }
}

import java.util.*;

class Solution {
    public String compressString(String s) {
        if (s == null || s.isEmpty()) return s;

        Deque<Character> stack = new ArrayDeque<>();
        StringBuilder compressed = new StringBuilder();

        for (char c : s.toCharArray()) {
            // 字符变化：先结算上一段连续字符。
            if (!stack.isEmpty() && stack.peek() != c) {
                compressed.append(stack.peek()).append(stack.size());
                stack.clear();
            }
            stack.push(c); // 相同字符继续累在栈里，size 就是次数。
        }

        // 别忘了最后一段。
        compressed.append(stack.peek()).append(stack.size());

        // 压缩后没有更短，则按题意返回原串。
        return compressed.length() < s.length() ? compressed.toString() : s;
    }
}

class Solution {
    public int calculate(String s) {
        long result = 0;      // 已经确定、可以提交的加减部分。
        long lastTerm = 0;    // 当前还可能继续参与乘除的最后一项。
        long number = 0;      // 正在读取的数字。
        char operator = '+';  // number 前面的运算符。

        for (int i = 0; i <= s.length(); i++) {
            char c = i < s.length() ? s.charAt(i) : '+'; // 末尾哨兵触发最后一次结算。

            if (i < s.length() && Character.isDigit(c)) {
                number = number * 10 + (c - '0');
                continue;
            }

            if (i < s.length() && c == ' ') {
                continue;
            }

            // 此时遇到了新的运算符，应先执行“上一轮保存的 operator”。
            switch (operator) {
                case '+':
                    result += lastTerm;
                    lastTerm = number;
                    break;
                case '-':
                    result += lastTerm;
                    lastTerm = -number;
                    break;
                case '*':
                    lastTerm = lastTerm * number;
                    break;
                case '/':
                    lastTerm = lastTerm / number; // Java 整数除法向 0 截断。
                    break;
                default:
                    throw new IllegalStateException("unexpected operator");
            }

            operator = c; // 这个运算符留给下一轮执行。
            number = 0;
        }

        return (int) (result + lastTerm);
    }
}

import java.util.*;

class Solution {
    public int calculate(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        int ans = 0, num = 0, sign = 1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                num = num * 10 + c - '0'; // 拼出多位数
            } else if (c == '+') {
                ans += sign * num;
                num = 0;
                sign = 1;
            } else if (c == '-') {
                ans += sign * num; // 先结算符号前的数，再把符号改成减
                num = 0;
                sign = -1;
            } else if (c == '(') {
                stack.push(ans);
                stack.push(sign); // 记下进入括号前的结果和这一层的符号
                ans = 0;
                sign = 1;
            } else if (c == ')') {
                ans += sign * num;
                num = 0;
                ans *= stack.pop(); // 先乘括号前的符号，再加回外层结果
                ans += stack.pop();
            }
        }
        return ans + sign * num; // 表达式末尾没有运算符，补上最后一个数
    }
}

import java.util.*;

class Solution {
    public int calculate(String s) {
        return dfs(s.toCharArray(), new int[]{0});
    }

    private int dfs(char[] arr, int[] idx) {
        Deque<Integer> stack = new ArrayDeque<>();
        int num = 0;
        char sign = '+';
        while (idx[0] < arr.length) {
            char c = arr[idx[0]];
            if (Character.isDigit(c)) {
                num = num * 10 + c - '0';
            }
            if (c == '(') {
                idx[0]++;
                num = dfs(arr, idx); // 括号内整段递归成一个数
            }
            // 运算符、右括号或最后一个字符时，按 sign 把 num 结算进栈
            if ((!Character.isDigit(c) && c != ' ') || idx[0] == arr.length - 1) {
                if (sign == '+') {
                    stack.push(num);
                } else if (sign == '-') {
                    stack.push(-num);
                } else if (sign == '*') {
                    stack.push(stack.pop() * num); // 乘除优先级高，立刻和前一项合并
                } else if (sign == '/') {
                    stack.push(stack.pop() / num);
                }
                if (c == ')') {
                    break; // 本层括号结束，下标留给外层继续加一
                }
                sign = c;
                num = 0;
            }
            idx[0]++;
        }
        int ans = 0;
        while (!stack.isEmpty()) {
            ans += stack.pop();
        }
        return ans;
    }
}
